# code generated by chatGPT

import random
import csv
from datetime import datetime
import os

# Constants representing the moves
ROCK = 'rock'
PAPER = 'paper'
SCISSORS = 'scissors'
MOVES = [ROCK, PAPER, SCISSORS]

# Define strategies
def random_strategy(history, my_history):
    return random.choice(MOVES)

def constant_strategy(history, my_history):
    return ROCK

def sequential_strategy(history, my_history):
    if not my_history:
        return ROCK
    last_move = my_history[-1]
    if last_move == ROCK:
        return PAPER
    elif last_move == PAPER:
        return SCISSORS
    elif last_move == SCISSORS:
        return ROCK

def mirror_strategy(history, my_history):
    if not history:
        return random.choice(MOVES)
    return history[-1]

def exclusion_strategy(history, my_history):
    if not history:
        return random.choice(MOVES)
    last_move = history[-1]
    return random.choice([move for move in MOVES if move != last_move])

def reaction_strategy(history, my_history):
    if not history:
        return random.choice(MOVES)
    last_move = history[-1]
    if last_move == ROCK:
        return PAPER
    elif last_move == PAPER:
        return SCISSORS
    elif last_move == SCISSORS:
        return ROCK

def reverse_mirror_strategy(history, my_history):
    if not history:
        return random.choice(MOVES)
    last_move = history[-1]
    if last_move == ROCK:
        return SCISSORS
    elif last_move == PAPER:
        return ROCK
    elif last_move == SCISSORS:
        return PAPER

def probability_weighted_strategy(history, my_history):
    if not history:
        return random.choice(MOVES)
    count_rock = history.count(ROCK)
    count_paper = history.count(PAPER)
    count_scissors = history.count(SCISSORS)
    total = len(history)
    prob_rock = count_rock / total
    prob_paper = count_paper / total
    prob_scissors = count_scissors / total
    move = random.choices(MOVES, weights=[prob_paper, prob_scissors, prob_rock])[0]
    return move

def multi_round_observation_strategy(history, my_history, rounds_to_observe=5):
    if len(history) < rounds_to_observe:
        return random.choice(MOVES)
    recent_moves = history[-rounds_to_observe:]
    count_rock = recent_moves.count(ROCK)
    count_paper = recent_moves.count(PAPER)
    count_scissors = recent_moves.count(SCISSORS)
    if count_rock > count_paper and count_rock > count_scissors:
        return PAPER  # Beat Rock
    elif count_paper > count_rock and count_paper > count_scissors:
        return SCISSORS  # Beat Paper
    elif count_scissors > count_rock and count_scissors > count_paper:
        return ROCK  # Beat Scissors
    else:
        return random.choice(MOVES)  # In case of a tie, choose randomly

# List of strategy functions
strategies = [
    random_strategy,
    constant_strategy,
    sequential_strategy,
    mirror_strategy,
    exclusion_strategy,
    reaction_strategy,
    reverse_mirror_strategy,
    probability_weighted_strategy,
    multi_round_observation_strategy
]

strategy_names = [
    "Random",
    "Constant",
    "Sequential",
    "Mirror",
    "Exclusion",
    "Reaction",
    "Reverse",
    "Probability-Weighted",
    "Multi-Round Observation"
]

def determine_winner(move1, move2):
    """
    Determine the winner between move1 and move2.
    """
    if move1 == move2:
        return 0  # Draw
    elif (move1 == ROCK and move2 == SCISSORS) or \
         (move1 == PAPER and move2 == ROCK) or \
         (move1 == SCISSORS and move2 == PAPER):
        return 1  # move1 wins
    else:
        return 2  # move2 wins

def simulate_match(strategy1, strategy2, rounds):
    """
    Simulate a match between two strategies for a given number of rounds.
    """
    history1 = []
    history2 = []
    results = {1: 0, 2: 0, 0: 0}  # Wins for Player 1, Player 2, and Draws

    for _ in range(rounds):
        move1 = strategy1(history2, history1)
        move2 = strategy2(history1, history2)
        winner = determine_winner(move1, move2)
        results[winner] += 1
        history1.append(move1)
        history2.append(move2)

    # Calculate probabilities
    prob_p1_win = (results[1] / rounds) * 100
    prob_p2_win = (results[2] / rounds) * 100
    prob_draw = (results[0] / rounds) * 100

    return results, prob_p1_win, prob_p2_win, prob_draw

def simulate_all_matches(rounds):
    """
    Simulate all strategy matchups for a given number of rounds and save results to a file.
    """
    results = []

    for i, strategy1 in enumerate(strategies):
        for j, strategy2 in enumerate(strategies):
            match_result, prob_p1_win, prob_p2_win, prob_draw = simulate_match(strategy1, strategy2, rounds)
            results.append({
                "P1 Strat": strategy_names[i],
                "P2 Strat": strategy_names[j],
                "P1 Wins": match_result[1],
                "P2 Wins": match_result[2],
                "Draws": match_result[0],
                "P1 Win %": f"{prob_p1_win:.2f}%",
                "P2 Win %": f"{prob_p2_win:.2f}%",
                "Draw %": f"{prob_draw:.2f}%"
            })

    # Generate a timestamp for the filename
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    
    # Directory path
    directory = 'WinRPS/data'
    
    # Create the directory if it doesn't exist
    os.makedirs(directory, exist_ok=True)
    
    # Full file path
    filename = os.path.join(directory, f'rps_strategy_results_{rounds}rounds_{timestamp}.csv')

    # Write results to a CSV file
    with open(filename, 'w', newline='') as file:
        fieldnames = ["P1 Strat", "P2 Strat", "P1 Wins", "P2 Wins", "Draws",
                      "P1 Win %", "P2 Win %", "Draw %"]
        writer = csv.DictWriter(file, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(results)

    print(f"Results saved to {filename}")

# Run the simulation for different round counts
round_counts = [50, 500, 5000, 50000]
for rounds in round_counts:
    simulate_all_matches(rounds)
    
